import type { ChatMessage, ChatStats, ParticipantStat, ResponseGapStats, WordStat } from "./types";

const STOP_WORDS = new Set([
  "the","and","that","this","with","you","your","for","are","was","were","have","has","had","but","not","from","they","them","their","what","when","where","who","why","how","can","could","would","should","will","just","like","really","very","then","than","there","here","been","being","because","about","into","onto","over","under","again","also","too","its","it's","im","i'm","ive","i've","dont","don't","didnt","didn't","cant","can't","wont","won't","yes","yeah","yep","nope","okay","ok","lol","haha","hahaha","https","http","www","com","image","omitted","video","audio","sticker","gif"
]);
const WEEKDAYS = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
const DAY = 86_400_000;
const HOUR = 3_600_000;
const HEART_SIGNAL = /(?:❤\uFE0F?|🩷|💙|💚|💛|💜|💕|💞|💓|💗|💖|💘|💝|💟)/gu;

function clamp(score: number) {
  return Math.max(0, Math.min(100, Math.round(score)));
}

function dayKey(timestamp: number) {
  const d = new Date(timestamp);
  return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
}

function monthKey(timestamp: number) {
  const date = new Date(timestamp);
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
}

function median(values: number[]) {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
}

function longestStreak(timestamps: number[]) {
  const days = [...new Set(timestamps.map(dayKey))].sort((a, b) => a - b);
  let best = days.length ? 1 : 0;
  let run = best;
  for (let i = 1; i < days.length; i++) {
    if (Math.round((days[i] - days[i - 1]) / DAY) === 1) run += 1;
    else run = 1;
    best = Math.max(best, run);
  }
  return best;
}

function longestSilence(timestamps: number[]) {
  const days = [...new Set(timestamps.map(dayKey))].sort((a, b) => a - b);
  let best = 0;
  for (let i = 1; i < days.length; i++) {
    best = Math.max(best, Math.max(0, Math.round((days[i] - days[i - 1]) / DAY) - 1));
  }
  return best;
}

function tokenize(text: string) {
  return text
    .toLowerCase()
    .replace(/https?:\/\/\S+/g, " ")
    .replace(/[^a-z0-9'’]+/g, " ")
    .split(/\s+/)
    .map((word) => word.replace(/[’']/g, "'"))
    .filter((word) => word.length >= 3 && !STOP_WORDS.has(word) && !/^\d+$/.test(word));
}

function responseGapBuckets(values: number[]): ResponseGapStats {
  const buckets: ResponseGapStats = { under5Minutes: 0, under30Minutes: 0, under2Hours: 0, under12Hours: 0, over12Hours: 0 };
  for (const minutes of values) {
    if (minutes < 5) buckets.under5Minutes += 1;
    else if (minutes < 30) buckets.under30Minutes += 1;
    else if (minutes < 120) buckets.under2Hours += 1;
    else if (minutes < 720) buckets.under12Hours += 1;
    else buckets.over12Hours += 1;
  }
  return buckets;
}

export function analyzeChat(messages: ChatMessage[]): ChatStats {
  if (!messages.length) throw new Error("No supported chat messages found.");
  const sorted = [...messages].sort((a, b) => a.timestamp - b.timestamp);
  const participantMap = new Map<string, ParticipantStat>();
  const replyGaps = new Map<string, number[]>();
  const allSenderChangeGaps: number[] = [];
  const boundedReplyGaps: number[] = [];
  const wordMap = new Map<string, number>();
  const hourCounts = Array(24).fill(0) as number[];
  const weekdayCounts = Array(7).fill(0) as number[];
  const yearMap = new Map<number, number>();
  const monthMap = new Map<string, number>();
  const dayCounts = new Map<number, number>();
  const activeDaySet = new Set<number>();
  const dayparts = { morning: 0, afternoon: 0, evening: 0, night: 0 };
  let totalWords = 0;
  let lateNightMessages = 0;
  let questionsAsked = 0;
  let laughSignals = 0;
  let heartSignals = 0;
  let mediaSignals = 0;

  for (let index = 0; index < sorted.length; index++) {
    const message = sorted[index];
    const words = tokenize(message.text);
    const questionCount = (message.text.match(/\?/g) ?? []).length;
    const laughCount = (message.text.match(/\b(?:ha){2,}|\blol+\b|😂|🤣/gi) ?? []).length;
    const heartCount = (message.text.match(HEART_SIGNAL) ?? []).length;
    const isMedia = /<media omitted>|image omitted|video omitted|audio omitted|sticker omitted/gi.test(message.text);
    const date = new Date(message.timestamp);
    const hour = date.getHours();
    const previous = index > 0 ? sorted[index - 1] : null;
    const gap = previous ? message.timestamp - previous.timestamp : null;
    const startsConversation = !previous || (gap !== null && gap > 6 * HOUR);

    totalWords += words.length;
    questionsAsked += questionCount;
    laughSignals += laughCount;
    heartSignals += heartCount;
    if (isMedia) mediaSignals += 1;

    const p = participantMap.get(message.sender) ?? {
      name: message.sender,
      messages: 0,
      percentage: 0,
      words: 0,
      avgWords: 0,
      questions: 0,
      conversationStarts: 0,
      lateNightMessages: 0,
      laughSignals: 0,
      heartSignals: 0,
      medianReplyMinutes: null,
    };
    p.messages += 1;
    p.words += words.length;
    p.questions += questionCount;
    p.laughSignals += laughCount;
    p.heartSignals += heartCount;
    if (startsConversation) p.conversationStarts += 1;
    if (hour >= 0 && hour < 5) p.lateNightMessages += 1;
    participantMap.set(message.sender, p);

    if (previous && previous.sender !== message.sender && gap !== null && gap > 0) {
      const minutes = gap / 60_000;
      allSenderChangeGaps.push(minutes);
      if (gap <= 12 * HOUR) {
        boundedReplyGaps.push(minutes);
        const senderReplies = replyGaps.get(message.sender) ?? [];
        senderReplies.push(minutes);
        replyGaps.set(message.sender, senderReplies);
      }
    }

    for (const word of words) wordMap.set(word, (wordMap.get(word) ?? 0) + 1);

    hourCounts[hour] += 1;
    weekdayCounts[date.getDay()] += 1;
    yearMap.set(date.getFullYear(), (yearMap.get(date.getFullYear()) ?? 0) + 1);
    const month = monthKey(message.timestamp);
    monthMap.set(month, (monthMap.get(month) ?? 0) + 1);
    const day = dayKey(message.timestamp);
    activeDaySet.add(day);
    dayCounts.set(day, (dayCounts.get(day) ?? 0) + 1);
    if (hour >= 0 && hour < 5) {
      lateNightMessages += 1;
      dayparts.night += 1;
    } else if (hour < 12) dayparts.morning += 1;
    else if (hour < 17) dayparts.afternoon += 1;
    else dayparts.evening += 1;
  }

  const participants = [...participantMap.values()]
    .map((p) => ({
      ...p,
      percentage: Number(((p.messages / sorted.length) * 100).toFixed(1)),
      avgWords: Number((p.words / Math.max(1, p.messages)).toFixed(1)),
      medianReplyMinutes: median(replyGaps.get(p.name) ?? []),
    }))
    .sort((a, b) => b.messages - a.messages);

  const topWords: WordStat[] = [...wordMap.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, 12)
    .map(([word, count]) => ({ word, count }));

  const peakHour = hourCounts.indexOf(Math.max(...hourCounts));
  const favoriteWeekdayIndex = weekdayCounts.indexOf(Math.max(...weekdayCounts));
  const firstTimestamp = sorted[0].timestamp;
  const lastTimestamp = sorted[sorted.length - 1].timestamp;
  const daysTogether = Math.max(1, Math.floor((lastTimestamp - firstTimestamp) / DAY) + 1);
  const laughRate = laughSignals / sorted.length;
  const heartRate = heartSignals / sorted.length;
  const questionRate = questionsAsked / sorted.length;
  const nightRate = lateNightMessages / sorted.length;
  const balance = participants.length >= 2 ? 100 - Math.abs(participants[0].percentage - participants[1].percentage) : 30;
  const [biggestDayTimestamp, biggestDayMessages] = [...dayCounts.entries()].sort((a, b) => b[1] - a[1])[0] ?? [firstTimestamp, 1];

  return {
    participants,
    totalMessages: sorted.length,
    totalWords,
    firstTimestamp,
    lastTimestamp,
    daysTogether,
    activeDays: activeDaySet.size,
    longestStreak: longestStreak(sorted.map((m) => m.timestamp)),
    longestSilenceDays: longestSilence(sorted.map((m) => m.timestamp)),
    medianReplyMinutes: median(boundedReplyGaps),
    biggestDay: { timestamp: biggestDayTimestamp, messages: biggestDayMessages },
    peakHour,
    peakHourMessages: hourCounts[peakHour],
    favoriteWeekday: WEEKDAYS[favoriteWeekdayIndex],
    lateNightMessages,
    questionsAsked,
    laughSignals,
    heartSignals,
    mediaSignals,
    dayparts,
    topWords,
    byYear: [...yearMap.entries()].sort((a, b) => a[0] - b[0]).map(([year, count]) => ({ year, messages: count })),
    byMonth: [...monthMap.entries()].sort((a, b) => a[0].localeCompare(b[0])).map(([month, count]) => ({ month, messages: count })),
    responseGaps: responseGapBuckets(allSenderChangeGaps),
    conversationBalance: Number(balance.toFixed(1)),
    vibe: {
      nightOwl: clamp(nightRate * 900 + 18),
      curiosity: clamp(questionRate * 320 + 22),
      chaos: clamp(laughRate * 500 + mediaSignals / Math.max(1, sorted.length) * 180 + 18),
      affection: clamp(heartRate * 850 + balance * 0.45 + 12),
    },
  };
}

export const MAX_CHAT_BYTES = 15 * 1024 * 1024;
export const MIN_CHAT_MESSAGES = 5;

export interface ChatFileMetadata { name: string; size: number; }

export function validateChatFileMetadata(file: ChatFileMetadata): string | null {
  const lower = file.name.toLowerCase();
  if (!lower.endsWith(".txt") && !lower.endsWith(".json")) return "Please choose a .txt WhatsApp export or a .json Telegram chat export.";
  if (file.size > MAX_CHAT_BYTES) return "That file is over 15 MB. Please export a smaller text-only chat and try again.";
  return null;
}

export function validateRawChatText(text: string): string | null {
  if (!text.trim()) return "That file is empty. Export a supported chat and try again.";
  return null;
}

export function tooFewMessagesError(count: number) { return `I found only ${count} supported message${count === 1 ? "" : "s"}. Export a supported single chat without media and try again.`; }

import type { ChatMessage, DateOrder } from "./types";

const ANDROID = /^(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}),\s+(\d{1,2}:\d{2}(?::\d{2})?\s*(?:AM|PM|am|pm)?)\s+-\s+([^:]+):\s?(.*)$/;
const IOS = /^\[(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}),\s+(\d{1,2}:\d{2}(?::\d{2})?\s*(?:AM|PM|am|pm)?)\]\s+([^:]+):\s?(.*)$/;
const TIMESTAMPED_LINE = /^\[?\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4},\s+\d{1,2}:\d{2}/;
const DIRECTION_MARKS = /[\u200e\u200f\u202a-\u202e\u2066-\u2069]/g;
const UNICODE_SPACES = /[\u00a0\u2007\u2009\u202f]/g;

function normalizeYear(year: number) {
  if (year < 100) return year >= 70 ? 1900 + year : 2000 + year;
  return year;
}

function normalizeExport(raw: string) {
  return raw
    .replace(DIRECTION_MARKS, "")
    .replace(UNICODE_SPACES, " ")
    .replace(/\r\n?/g, "\n");
}

function parseTime(timeRaw: string) {
  const match = timeRaw.trim().match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)?$/i);
  if (!match) return null;

  let hour = Number(match[1]);
  const minute = Number(match[2]);
  const second = Number(match[3] ?? 0);
  const meridiem = match[4]?.toUpperCase();

  if (minute > 59 || second > 59) return null;

  if (meridiem) {
    if (hour < 1 || hour > 12) return null;
    if (meridiem === "PM" && hour < 12) hour += 12;
    if (meridiem === "AM" && hour === 12) hour = 0;
  } else if (hour > 23) {
    return null;
  }

  return { hour, minute, second };
}

function parseDate(dateRaw: string, timeRaw: string, order: DateOrder) {
  const parts = dateRaw.split(/[\/.\-]/).map(Number);
  if (parts.length !== 3 || parts.some((part) => !Number.isInteger(part))) return null;

  const [a, b, rawYear] = parts;
  const year = normalizeYear(rawYear);
  let month: number;
  let day: number;

  // "auto" is intentionally US-first for ambiguous dates, while dates whose
  // first field cannot be a month are treated as DD/MM.
  if (order === "dmy" || (order === "auto" && a > 12)) {
    day = a;
    month = b;
  } else {
    month = a;
    day = b;
  }

  const time = parseTime(timeRaw);
  if (!time || month < 1 || month > 12 || day < 1 || day > 31) return null;

  const date = new Date(year, month - 1, day, time.hour, time.minute, time.second);
  if (Number.isNaN(date.getTime())) return null;

  // Date normalizes impossible dates (for example Feb 31 -> Mar 3). Require
  // every requested component to round-trip unchanged before accepting it.
  if (
    date.getFullYear() !== year ||
    date.getMonth() !== month - 1 ||
    date.getDate() !== day ||
    date.getHours() !== time.hour ||
    date.getMinutes() !== time.minute ||
    date.getSeconds() !== time.second
  ) {
    return null;
  }

  return date.getTime();
}

export function parseChat(raw: string, order: DateOrder = "auto"): ChatMessage[] {
  const lines = normalizeExport(raw).split("\n");
  const messages: ChatMessage[] = [];

  for (const line of lines) {
    const match = line.match(ANDROID) ?? line.match(IOS);
    if (match) {
      const timestamp = parseDate(match[1], match[2], order);
      if (!timestamp) continue;

      const sender = match[3].trim();
      if (!sender || /messages and calls are end-to-end encrypted/i.test(sender)) continue;

      messages.push({ sender, timestamp, text: match[4] ?? "" });
      continue;
    }

    // Timestamped system/malformed lines must never become part of the prior
    // user's message. Ordinary non-timestamped continuation lines are allowed.
    if (TIMESTAMPED_LINE.test(line)) continue;

    if (messages.length && line.trim()) {
      messages[messages.length - 1].text += `\n${line.trim()}`;
    }
  }

  return messages;
}

